use interval_merge::merge_intervals;

#[test]
fn test_basic_merge() {
    let input = vec![[1, 3], [2, 6], [8, 10], [15, 18]];
    assert_eq!(merge_intervals(input), vec![[1, 6], [8, 10], [15, 18]]);
}

#[test]
fn test_no_overlap() {
    let input = vec![[1, 2], [3, 4], [5, 6]];
    assert_eq!(merge_intervals(input), vec![[1, 2], [3, 4], [5, 6]]);
}

#[test]
fn test_all_overlap() {
    let input = vec![[1, 10], [2, 5], [3, 8]];
    assert_eq!(merge_intervals(input), vec![[1, 10]]);
}

#[test]
fn test_adjacent_merge() {
    // [1,2] and [2,3] share endpoint — should merge to [1,3]
    let input = vec![[1, 2], [2, 3]];
    assert_eq!(merge_intervals(input), vec![[1, 3]]);
}

#[test]
fn test_single_interval() {
    assert_eq!(merge_intervals(vec![[5, 7]]), vec![[5, 7]]);
}

#[test]
fn test_empty() {
    let empty: Vec<[i32; 2]> = vec![];
    let result: Vec<[i32; 2]> = merge_intervals(empty);
    assert!(result.is_empty());
}

#[test]
fn test_unsorted_input() {
    // Input not pre-sorted — function must sort first
    let input = vec![[15, 18], [1, 3], [2, 6], [8, 10]];
    assert_eq!(merge_intervals(input), vec![[1, 6], [8, 10], [15, 18]]);
}
